{
  "status": "SUPPORTED",
  "task_summary": "Find a fastener and tool, fasten the target, and leave the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "The physical component (e.g., screw, bolt) to be attached.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "nut", "rivet", "clip"],
        "required_properties": ["threaded", "metal", "small"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastener.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "driver", "hammer"],
        "required_properties": ["handle", "driving_tip", "rigid"]
      },
      {
        "id": "target",
        "entity_kind": "FIXED_TARGET",
        "function": "The assembly or object at the marked location that needs fastening.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["assembly", "bracket", "plate", "workpiece"],
        "required_properties": ["hole", "surface", "rigid"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where reusable equipment is left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["surface", "horizontal"]
      }
    ],
    "functional_relations": [
      {
        "id": "compatible_for_fastening",
        "relation": "The fastener must be physically compatible with the target.",
        "participant_roles": ["fastener", "target"]
      ,
        "required": true
      },
      {
        "id": "operates_on",
        "relation": "The tool is used to manipulate the fastener.",
        "participant_roles": ["tool", "fastener"],
        "required": true
      },
      {
        "id": "placed_on",
        "relation": "The tool must be placed on the workbench after use.",
        "participant_roles": ["tool", "workbench"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_components",
        "operation": "Search for compatible fastener and tool.",
        "participant_roles": ["fastener", "tool"],
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "Attach fastener to target using tool.",
        "participant_roles": ["tool", "fastener", "target"],
        "operation_count": 1
      },
      {
        "id": "store_tool",
        "operation": "Place tool on workbench.",
        "participant_roles": ["tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastener": [],
      "tool": [],
      "target": [],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "Wooden workbench with drawers and legs."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "drawer_left",
        "label": "left_drawer",
        "visual_description": "Closed drawer under the left side of the workbench.",
        "reason": "Closed storage structure likely containing small hardware or tools."
      },
      {
        "id": "drawer_right",
        "label": "right_drawer",
        "visual_description": "Closed drawer under the right side of the workbench.",
        "reason": "Closed storage structure likely containing small hardware or tools."
      },
      {
        "id": "cabinet",
        "label": "blue_cabinet",
        "visual_description": "Tall closed cabinet next to the monitor.",
        "reason": "Closed storage structure likely containing larger tools or materials."
      }
    ],
    "inspection_order": [
      "drawer_left",
      "drawer_right",
      "cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
  }
